import { MEDIA } from './media.gen';
import type { CameraRoll, MediaSource, Reel, Slot, SlotRole } from './schema';

/**
 * The hero's sample reels and camera roll, from the owner's own footage. The measured facts (cuts, beats, files, sizes)
 * are generated by scripts/media.mjs into media.gen.ts; the words (what each slot needs, why each clip was picked)
 * are written here by a person who looked at the frames. Every reel and the roll are labelled as samples on the page.
 *
 * The roll is honestly "clips from the same trip": each shot of a reel is one clip in it, with a short loop and frames
 * in the sprite atlas. `timing: 'estimated'` means the slots are FFmpeg's scene cuts and the beats a grid estimated from
 * the reel's audio; Taalcut's own breakdown replaces both when its template JSON is in the footage folder.
 */

/** What scripts/media.mjs writes. */
export interface MediaManifest {
  readonly encoders: { readonly mp4: string; readonly webm: string | null; readonly image: string };
  /** Bytes in all and a loop at most, and why the budget is what it is. */
  readonly budget: { readonly total: number; readonly loop: number; readonly reason?: string };
  readonly totalBytes: number;
  readonly reels: readonly MediaReel[];
  readonly roll: {
    readonly atlas: (ServedFile & { readonly columns: number; readonly rows: number; readonly cell: readonly number[] }) | null;
    readonly clips: readonly MediaClip[];
    readonly frames: readonly { readonly sprite: number; readonly clipId: string; readonly at: number }[];
  };
}

export interface ServedFile {
  readonly src: string;
  readonly bytes: number;
}

/** A served video: its type, and the frame size, rate (fps) and target bitrate (kbit/s) it was made at. */
type ServedVideo = ServedFile & { readonly type: string; readonly width: number; readonly height: number; readonly fps: number; readonly kbps: number };

export interface MediaReel {
  readonly id: string;
  /** The footage file's name (never served). */
  readonly source: string;
  /** The footage's own frame size, rate and codec: nothing served is larger. */
  readonly sourceSize: { readonly width: number; readonly height: number; readonly fps: number; readonly codec: string };
  readonly durationSec: number;
  readonly fps: number;
  readonly day: string;
  /** Where `day` came from: the file's creation_time, or only the file's own date. */
  readonly dayFrom: string;
  readonly timing: 'breakdown' | 'estimated';
  readonly tempo: number;
  readonly beats: readonly number[];
  /** Shots between cuts; `cutScore` is how sure the scene detector was of the cut that opens it. */
  readonly shots: readonly { readonly start: number; readonly end: number; readonly cutScore: number | null }[];
  readonly sureCutScore: number;
  readonly poster: readonly (ServedFile & { readonly width: number; readonly height: number })[];
  readonly reference: readonly ServedVideo[];
  readonly made: readonly ServedVideo[];
}

export interface MediaClip {
  readonly id: string;
  readonly reelId: string | null;
  readonly day: string;
  readonly sprite: number;
  readonly durationSec: number;
  readonly loopStart: number;
  readonly loop: readonly ServedVideo[];
}

/** The words for a reel's shelf card and each of its shots, in shot order. */
interface ReelWords {
  readonly label: string;
  readonly title: string;
  /** What the camera roll calls this reel's shots when the footage carries no shoot date ("Vietnam trip"). */
  readonly roll: string;
  /**
   * Per shot: what the slot needs, in a few words of its own (no two slots read the same; the app's cast grid shows
   * this line, never a reason per pick), and a note on the picked clip, true to its frames, for the ledger's tests.
   */
  readonly shots: readonly (readonly [needs: string, reason: string])[];
}

