/**
 * A shot's job, from the cut rhythm: the first opens (hook), the last closes (outro), shots much shorter than the
 * reel's usual shot are the fast run (peak), and the rest build.
 */
export function roleOf(index: number, count: number, length: number, usual: number): SlotRole {
  if (index === 0) return 'hook';
  if (index === count - 1) return 'outro';
  return length < usual * 0.75 ? 'peak' : 'build';
}

function median(values: readonly number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)] ?? 0;
}

function sources(files: readonly ServedVideo[]): MediaSource[] {
  return files.map((f) => ({ src: f.src, type: f.type as MediaSource['type'] }));
}

function clipIdOf(reelId: string, shot: number): string {
  return `${reelId}-${String(shot + 1).padStart(2, '0')}`;
}

function toReel(media: MediaReel, words: ReelWords): Reel {
  const lengths = media.shots.map((s) => s.end - s.start);
  const usual = median(lengths.slice(1, -1).length ? lengths.slice(1, -1) : lengths);
  const slots: Slot[] = media.shots.map((shot, i) => {
    const [needs, reason] = words.shots[i] ?? ['', ''];
    return {
      id: `${media.id}-slot-${i + 1}`,
      role: roleOf(i, media.shots.length, lengths[i] ?? 0, usual),
      start: shot.start,
      end: shot.end,
      needs,
      pick: { clipId: clipIdOf(media.id, i), reason, alternates: 3 },
      ...(shot.cutScore !== null && shot.cutScore < media.sureCutScore ? { uncertainCut: true } : {}),
    };
  });
  return {
    id: media.id,
    label: words.label,
    title: words.title,
    project: words.roll,
    durationSec: media.durationSec,
    tempo: media.tempo,
    beats: media.beats,
    slots,
    poster: media.poster[0]?.src ?? '',
    reference: sources(media.reference),
    made: sources(media.made),
    timing: media.timing,
  };
}

/**
 * Every encoded reel that has its words, in REEL_WORDS's order (the first is the one the page opens on). A reel without
 * them is left out (test/unit/media-manifest.test.ts fails).
 */
const ENCODED: readonly Reel[] = Object.entries(REEL_WORDS).flatMap(([id, words]) => {
  const media = MEDIA.reels.find((m) => m.id === id);
  return media ? [toReel(media, words)] : [];
});

/** The shelf holds at least this many reels; placeholders keep the places the owner's footage hasn't filled yet. */
export const SHELF_MIN = 3;

/**
 * A shelf place waiting for one of the owner's reels (placeholder: true): no media, no template, nothing to pick. The
 * hero shows it as an empty place, never as a reel. Each goes as soon as enough real reels are encoded.
 */
const PLACEHOLDERS: readonly Reel[] = [
  ['food', 'Food', 'Street food, one night'],
  ['day', 'Day', 'A day, start to finish'],
].map(([id = '', label = '', title = '']) => ({
  id,
  label,
  title,
  durationSec: 0,
  tempo: 120,
  beats: [],
  slots: [],
  poster: '',
  reference: [],
  made: [],
  timing: 'estimated',
  placeholder: true,
}));

export const REELS: readonly Reel[] = [...ENCODED, ...PLACEHOLDERS.slice(0, Math.max(0, SHELF_MIN - ENCODED.length))];

/** The reels with footage and a template: the only ones a visitor can choose, and the ones the demos run. */
export const SAMPLE_REELS: readonly Reel[] = REELS.filter((r) => !r.placeholder);

/** The default cut the page opens on, and the one `/` without `?reel=` shows. */
export const DEFAULT_REEL_ID: string = ENCODED[0]?.id ?? REELS[0]?.id ?? 'vietnam';

export function reelById(id: string | null | undefined): Reel {
  return REELS.find((r) => r.id === id) ?? REELS.find((r) => r.id === DEFAULT_REEL_ID) ?? (REELS[0] as Reel);
}

/** A reel's small poster (540×960) for the shelf, beside `poster` (1080×1920). */
export function smallPoster(reelId: string): string | undefined {
  return MEDIA.reels.find((r) => r.id === reelId)?.poster[1]?.src;
}

const ATLAS = MEDIA.roll.atlas;

/** The sample camera roll: every shot is a clip, grouped by day; the atlas holds its frames. */
export const CAMERA_ROLL: CameraRoll = {
  atlas: {
    src: ATLAS?.src ?? '/media/roll/atlas.webp',
    columns: ATLAS?.columns ?? 16,
    rows: ATLAS?.rows ?? 0,
    cell: [ATLAS?.cell[0] ?? 252, ATLAS?.cell[1] ?? 448],
  },
  clips: MEDIA.roll.clips.map((c) => ({ id: c.id, day: c.day, sprite: c.sprite, durationSec: c.durationSec })),
  shownCount: 1284,
};

/** Every frame in the atlas, with the clip it comes from: more of the roll to fill a dense wall honestly. */
export const ROLL_FRAMES: readonly { readonly sprite: number; readonly clipId: string; readonly at: number }[] = MEDIA.roll.frames;

/** A roll clip's short loop (silent MP4), for a pick landing in its slot. */
export function rollClipLoop(clipId: string): readonly MediaSource[] {
  return sources(MEDIA.roll.clips.find((c) => c.id === clipId)?.loop ?? []);
}

/**
 * A roll day's heading when its date can't be trusted: the footage carried no shoot date (`dayFrom: 'file date'`), so
 * the day is only when the file was copied, and the roll names the trip instead. Undefined when the date is real.
 */
export function undatedDayHeading(day: string): string | undefined {
  const reel = MEDIA.reels.find((r) => r.day === day && r.dayFrom === 'file date');
  return reel ? (REEL_WORDS[reel.id]?.roll ?? REEL_WORDS[reel.id]?.label) : undefined;
}
